// Vapi sends: body.message.toolCallList[0] = { id, function: { name, arguments } }
const body = $input.first().json.body || {};
const msg = body.message || {};
const calls = msg.toolCallList || msg.toolCalls || [];
const call = calls[0] || {};
const fn = call.function || {};
let args = fn.arguments || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
const q = $input.first().json.query || {};
return [{ json: { toolCallId: call.id || 'test', name: fn.name || '', args, client: q.client || '',
  assistantId: (msg.call && msg.call.assistantId) || (msg.assistant && msg.assistant.id) || '', phoneNumberId: (msg.call && msg.call.phoneNumberId) || '' } }];

const C = $('Client (Pricing)').first().json;
// One API call reads both tabs (faster than two Sheets nodes)
function dur(v) {
  const s = String(v ?? '').trim();
  if (!/^\d+$/.test(s)) return s;
  const m = Number(s), h = Math.floor(m / 60), r = m % 60;
  return [h ? h + (h === 1 ? ' hour' : ' hours') : '', r ? r + ' minutes' : ''].filter(Boolean).join(' ') || '0 minutes';
}
const toolCallId = $('Parse Tool Call').first().json.toolCallId;
const vr = $('Read Sheet Tabs').first().json.valueRanges || [];
const rows = i => { const v = (vr[i] || {}).values || []; const [hdr = [], ...rest] = v; return rest.map(r => Object.fromEntries(hdr.map((k, j) => [k, r[j] ?? '']))); };
const services = rows(0).filter(r => r.service);
const packages = rows(1).filter(r => r.package);
if (!services.length) {
  return [{ json: { results: [{ toolCallId, result: 'PRICE LIST TEMPORARILY UNAVAILABLE. Apologise briefly, and offer to have the team call the customer back (use escalate_to_human).' }] } }];
}
const s = services.map(r => `${r.service}: ${r.price_pkr} ${C.currency_word} (${dur(r.duration)})`).join('; ');
const p = packages.map(r => `${r.package} (${r.includes}): ${r.price_pkr} ${C.currency_word} (${dur(r.duration)})${r.notes ? ' - ' + r.notes : ''}`).join('; ');
return [{ json: { results: [{ toolCallId, result: `SERVICES: ${s}. PACKAGES: ${p}. All prices are fixed, in ${C.currency_word} (${C.currency_code}). Never use any other currency.` }] } }];

// Vapi sends: body.message.toolCallList[0] = { id, function: { name, arguments } }
const body = $input.first().json.body || {};
const msg = body.message || {};
const calls = msg.toolCallList || msg.toolCalls || [];
const call = calls[0] || {};
const fn = call.function || {};
let args = fn.arguments || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
const q = $input.first().json.query || {};
return [{ json: { toolCallId: call.id || 'test', name: fn.name || '', args, client: q.client || '',
  assistantId: (msg.call && msg.call.assistantId) || (msg.assistant && msg.assistant.id) || '', phoneNumberId: (msg.call && msg.call.phoneNumberId) || '' } }];

const C = $('Client (Availability)').first().json;
const TZ = C.timezone;
const P = $('Parse Availability Call').first().json;
const args = P.args || {};
const toolCallId = P.toolCallId;
const reply = result => [{ json: { results: [{ toolCallId, result }] } }];

// Settings tab -> { key: value }
const S = {};
$('Read Settings').all().forEach(i => { if (i.json.key) S[String(i.json.key).trim()] = String(i.json.value ?? '').trim(); });

// Helpers
const toMin = v => { const s = String(v ?? '').toLowerCase().trim(); if (/^\d+$/.test(s)) return Number(s);
  const h = s.match(/(\d+)\s*hour/), m = s.match(/(\d+)\s*min/); return ((h ? +h[1] * 60 : 0) + (m ? +m[1] : 0)) || 60; };
const words = min => { const h = Math.floor(min / 60), r = min % 60;
  return [h ? h + (h === 1 ? ' hour' : ' hours') : '', r ? r + ' minutes' : ''].filter(Boolean).join(' '); };
const hm = t => { const [h, m] = String(t).split(':').map(Number); return h * 60 + (m || 0); };
const fmt = min => { let h = Math.floor(min / 60); const m = min % 60, ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12; return `${h}:${String(m).padStart(2, '0')} ${ap}`; };
const pkMin = d => { const [h, m] = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false }).format(d).split(':'); return (+h % 24) * 60 + (+m); };

// 1. Date checks
const date = String(args.date || '').trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return reply('Date missing. Ask the customer which day, then call again with date as YYYY-MM-DD.');
const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
if (date < today) return reply(`${date} is in the past. Ask the customer for a future date.`);
const weekday = new Date(date + 'T12:00:00' + C.offset).toLocaleDateString('en-US', { weekday: 'long', timeZone: TZ });
const openDays = (S.open_days || '').split(',').map(d => d.trim().slice(0, 3).toLowerCase());
if (!openDays.includes(weekday.slice(0, 3).toLowerCase())) return reply(`The salon is closed on ${weekday}, ${date}. Open days: ${S.open_days}. Suggest another day.`);

// 2. Service duration
const want = String(args.service || '').toLowerCase().trim();
const all = [...$('Services For Availability').all().map(i => ({ name: i.json.service, d: i.json.duration })),
             ...$('Packages For Availability').all().map(i => ({ name: i.json.package, d: i.json.duration }))].filter(x => x.name);
const findItem = (list, raw) => { const k = s => String(s || '').toLowerCase().replace(/\(.*?\)/g, ' ').replace(/[^a-z0-9+]/g, ''); const w = k(raw); if (!w) return null; const by = f => list.filter(x => f(k(x.name))); return by(n => n === w)[0] || by(n => w.startsWith(n)).sort((a, b) => k(b.name).length - k(a.name).length)[0] || by(n => n.includes(w)).sort((a, b) => k(a.name).length - k(b.name).length)[0] || by(n => w.includes(n)).sort((a, b) => k(b.name).length - k(a.name).length)[0] || null; };
const match = want ? findItem(all, args.service) : null;
const dur = match ? toMin(match.d) : 60;
const label = match ? match.name : 'The appointment';
const note = want && !match ? ` (service "${args.service}" not found in the list, assumed 1 hour)` : '';

// 3. Opening hours, capacity, existing bookings
const open = hm(S.open_time || '11:00'), close = hm(S.close_time || '21:00');
const maxPar = Number(S.max_parallel_bookings) || 1;
const events = $('Get Day Bookings').all().map(i => i.json)
  .filter(e => e.start && e.start.dateTime && e.status !== 'cancelled')
  .map(e => ({ s: pkMin(new Date(e.start.dateTime)), e: pkMin(new Date(e.end.dateTime)) }));
const earliest = date === today ? pkMin(new Date()) + 30 : 0; // 30 min buffer for same-day
const isFree = st => st >= open && st + dur <= close && st >= earliest &&
  events.filter(ev => st < ev.e && st + dur > ev.s).length < maxPar;

const slots = [];
for (let t = open; t + dur <= close; t += 30) if (isFree(t)) slots.push(t);
const hours = `Open ${fmt(open)} to ${fmt(close)}.`;

// 4. Answer
if (args.time) {
  const t = hm(args.time);
  if (isFree(t)) return reply(`AVAILABLE: ${label} on ${weekday}, ${date} at ${fmt(t)} is free (takes ${words(dur)})${note}.`);
  const why = (t < open || t + dur > close) ? `outside business hours, ${fmt(open)} to ${fmt(close)}` : (t < earliest ? 'too soon or already passed' : 'already booked');
  if (!slots.length) return reply(`NOT AVAILABLE: ${date} is fully booked for ${label}${note}. Suggest another day.`);
  const near = [...slots].sort((a, b) => Math.abs(a - t) - Math.abs(b - t)).slice(0, 3).sort((a, b) => a - b);
  return reply(`NOT AVAILABLE at ${fmt(t)} on ${weekday}, ${date} (${why}). Nearest free times for ${label}: ${near.map(fmt).join(', ')}${note}.`);
}
if (!slots.length) return reply(`${weekday}, ${date} is fully booked for ${label}${note}. Suggest another day.`);
const shown = slots.length > 8 ? slots.filter((_, i) => i % Math.ceil(slots.length / 8) === 0) : slots;
return reply(`Free start times on ${weekday}, ${date} for ${label} (takes ${words(dur)}): ${shown.map(fmt).join(', ')}. ${hours}${note}`);

// Vapi sends: body.message.toolCallList[0] = { id, function: { name, arguments } }
const body = $input.first().json.body || {};
const msg = body.message || {};
const calls = msg.toolCallList || msg.toolCalls || [];
const call = calls[0] || {};
const fn = call.function || {};
let args = fn.arguments || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
const q = $input.first().json.query || {};
return [{ json: { toolCallId: call.id || 'test', name: fn.name || '', args, client: q.client || '',
  assistantId: (msg.call && msg.call.assistantId) || (msg.assistant && msg.assistant.id) || '', phoneNumberId: (msg.call && msg.call.phoneNumberId) || '' } }];

const C = $('Client (Booking)').first().json;
const TZ = C.timezone;
const P = $('Parse Booking Call').first().json;
const args = P.args || {};
const no = result => [{ json: { ok: false, result } }];

// Settings tab -> { key: value }
const S = {};
$('Booking Settings').all().forEach(i => { if (i.json.key) S[String(i.json.key).trim()] = String(i.json.value ?? '').trim(); });

// Helpers
const toMin = v => { const s = String(v ?? '').toLowerCase().trim(); if (/^\d+$/.test(s)) return Number(s);
  const h = s.match(/(\d+)\s*hour/), m = s.match(/(\d+)\s*min/); return ((h ? +h[1] * 60 : 0) + (m ? +m[1] : 0)) || 60; };
const words = min => { const h = Math.floor(min / 60), r = min % 60;
  return [h ? h + (h === 1 ? ' hour' : ' hours') : '', r ? r + ' minutes' : ''].filter(Boolean).join(' '); };
const hm = t => { const [h, m] = String(t).split(':').map(Number); return h * 60 + (m || 0); };
const fmt = min => { let h = Math.floor(min / 60); const m = min % 60, ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12; return `${h}:${String(m).padStart(2, '0')} ${ap}`; };
const hhmm = min => `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;
const pkMin = d => { const [h, m] = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false }).format(d).split(':'); return (+h % 24) * 60 + (+m); };

// 1. Required details
const name = String(args.name || '').trim();
let phone = String(args.phone || '').replace(/\D/g, '');
if (phone.startsWith('0')) phone = C.country_code + phone.slice(1);       // 03001234567 -> 923001234567
if (C.country_code === '92' && phone.length === 10 && phone.startsWith('3')) phone = '92' + phone;
const service = String(args.service || '').trim();
const date = String(args.date || '').trim();
const time = String(args.time || '').trim();
const missing = [];
if (!name) missing.push('customer name');
if (phone.length < 11) missing.push('valid phone number');
if (!service) missing.push('service');
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) missing.push('date');
if (!/^\d{1,2}:\d{2}$/.test(time)) missing.push('time');
if (missing.length) return no(`NOT BOOKED: missing ${missing.join(', ')}. Ask the customer, then call book_appointment again.`);

// 2. Day checks
const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
if (date < today) return no(`NOT BOOKED: ${date} is in the past. Ask for a future date.`);
const weekday = new Date(date + 'T12:00:00' + C.offset).toLocaleDateString('en-US', { weekday: 'long', timeZone: TZ });
const openDays = (S.open_days || '').split(',').map(d => d.trim().slice(0, 3).toLowerCase());
if (!openDays.includes(weekday.slice(0, 3).toLowerCase())) return no(`NOT BOOKED: the salon is closed on ${weekday}. Open days: ${S.open_days}.`);

// 3. Service lookup (name, duration, price)
const want = service.toLowerCase();
const all = [...$('Booking Services').all().map(i => ({ name: i.json.service, d: i.json.duration, p: i.json.price_pkr })),
             ...$('Booking Packages').all().map(i => ({ name: i.json.package, d: i.json.duration, p: i.json.price_pkr }))].filter(x => x.name);
const findItem = (list, raw) => { const k = s => String(s || '').toLowerCase().replace(/\(.*?\)/g, ' ').replace(/[^a-z0-9+]/g, ''); const w = k(raw); if (!w) return null; const by = f => list.filter(x => f(k(x.name))); return by(n => n === w)[0] || by(n => w.startsWith(n)).sort((a, b) => k(b.name).length - k(a.name).length)[0] || by(n => n.includes(w)).sort((a, b) => k(a.name).length - k(b.name).length)[0] || by(n => w.includes(n)).sort((a, b) => k(b.name).length - k(a.name).length)[0] || null; };
const match = findItem(all, service);
if (!match) return no(`NOT BOOKED: "${service}" is not in our service list. Offer the customer the correct service name first.`);
const dur = toMin(match.d);

// 4. Re-check the slot (someone may have booked it moments ago)
const open = hm(S.open_time || '11:00'), close = hm(S.close_time || '21:00');
const maxPar = Number(S.max_parallel_bookings) || 1;
const events = $('Booking Day Events').all().map(i => i.json)
  .filter(e => e.start && e.start.dateTime && e.status !== 'cancelled')
  .map(e => ({ s: pkMin(new Date(e.start.dateTime)), e: pkMin(new Date(e.end.dateTime)) }));
const earliest = date === today ? pkMin(new Date()) + 30 : 0;
const isFree = st => st >= open && st + dur <= close && st >= earliest &&
  events.filter(ev => st < ev.e && st + dur > ev.s).length < maxPar;
const t = hm(time);
if (!isFree(t)) {
  const slots = []; for (let x = open; x + dur <= close; x += 30) if (isFree(x)) slots.push(x);
  const near = slots.sort((a, b) => Math.abs(a - t) - Math.abs(b - t)).slice(0, 3).sort((a, b) => a - b);
  return no(`NOT BOOKED: ${fmt(t)} on ${weekday} is not available for ${match.name}.` +
    (near.length ? ` Nearest free times: ${near.map(fmt).join(', ')}.` : ' That day is fully booked, suggest another day.'));
}

// 5. Everything OK -> build booking
const bookingId = 'BK-' + date.slice(5).replace('-', '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const nice = new Date(date + 'T12:00:00' + C.offset).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: TZ });
const ownerMsg = [
  `✅ New Booking - ${S.business_name || 'Salon'}`,
  `Name: ${name}`, `Phone: +${phone}`,
  `Service: ${match.name} (${words(dur)})`, `Price: ${C.currency_code} ${match.p}`,
  `Date: ${weekday}, ${nice}`, `Time: ${fmt(t)}`,
  `Booking ID: ${bookingId}`, args.notes ? `Notes: ${args.notes}` : ''
].filter(Boolean).join('\n');

return [{ json: {
  ok: true,
  bookingId, name, phone: '+' + phone, service: match.name, price: match.p, durationText: words(dur),
  date, time: hhmm(t), timeText: fmt(t), weekday,
  start: `${date}T${hhmm(t)}:00${C.offset}`, end: `${date}T${hhmm(t + dur)}:00${C.offset}`,
  notes: args.notes || '', ownerWhatsapp: String(S.owner_whatsapp || '').replace(/\D/g, ''),
  callmebotKey: S.callmebot_apikey || '', ownerMsg,
  ownerEmail: S.owner_email || '',
  waPhoneId: String(S.wa_phone_number_id || '').replace(/\D/g, ''),
  businessName: S.business_name || 'Salon',
  dateText: `${weekday}, ${nice}`,
  result: `BOOKED: ${match.name} for ${name} on ${weekday}, ${nice} at ${fmt(t)} (${words(dur)}, ${match.p} ${C.currency_word}). Booking ID ${bookingId}. Confirm these details to the customer.`
} }];

