const P = $('Parse Escalation Call').first().json;
const a = P.args || {};
const S = {};
$('Escalation Settings').all().forEach(i => { if (i.json.key) S[String(i.json.key).trim()] = String(i.json.value ?? '').trim(); });

let phone = String(a.phone || '').replace(/\D/g, '');
if (phone.startsWith('0')) phone = C.country_code + phone.slice(1);
if (C.country_code === '92' && phone.length === 10 && phone.startsWith('3')) phone = '92' + phone;
const phoneText = phone.length >= 11 ? '+' + phone : 'not given (check call log)';
const name = String(a.name || '').trim() || 'Unknown caller';
const reason = String(a.reason || 'Customer asked to speak to a person').trim();
const details = String(a.details || '').trim();

const now = new Date();
const id = 'CB-' + now.toLocaleDateString('en-CA', { timeZone: C.timezone }).slice(5).replace('-', '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const when = now.toLocaleString('en-GB', { timeZone: C.timezone, dateStyle: 'medium', timeStyle: 'short' });

const ownerMsg = [
  `📞 Callback needed - ${S.business_name || 'Salon'}`,
  `Name: ${name}`, `Phone: ${phoneText}`,
  `Reason: ${reason}`, details ? `Details: ${details}` : '',
  `Time: ${when}`, `Ref: ${id}`,
  `Please call the customer back as soon as possible.`
].filter(Boolean).join('\n');

return [{ json: {
  id, name, phone: phoneText, reason, details, ownerMsg,
  ownerWhatsapp: String(S.owner_whatsapp || '').replace(/\D/g, ''),
  ownerEmail: S.owner_email || '',
  waPhoneId: String(S.wa_phone_number_id || '').replace(/\D/g, ''),
  businessName: S.business_name || 'Salon',
  row: { booking_id: id, timestamp: now.toLocaleString('en-GB', { timeZone: C.timezone }), name, phone: phoneText,
         service: details, date: '', time: '', channel: 'call', status: 'callback_requested', calendar_event_id: '', call_summary: reason },
  result: `ESCALATED: The owner has been alerted (reason: ${reason}). Tell the customer politely that a team member will call them back shortly${phone.length >= 11 ? ' on ' + phoneText : ''}. Reference ${id}.`
} }];

const P = $('Parse Tool Call').first().json;
const vals = $input.first().json.values || [];
const [hdr = [], ...rows] = vals;
const list = rows.map(r => Object.fromEntries(hdr.map((k, j) => [String(k).trim(), String(r[j] ?? '').trim()])))
  .filter(c => c.client_id && String(c.active || 'yes').toLowerCase() !== 'no');
const has = (f, v) => !!v && String(f || '').split(',').map(s => s.trim()).includes(v);
// Which client is this call for? 1) ?client= in tool URL  2) phone number id  3) Vapi assistant id  4) first client
const c = list.find(x => P.client && x.client_id === P.client) || list.find(x => has(x.phone_number_ids, P.phoneNumberId))
  || list.find(x => has(x.vapi_assistant_ids, P.assistantId)) || list[0];
if (!c) throw new Error('No active client in the Clients registry');
const tz = c.timezone || 'Asia/Karachi';
const today = new Date().toLocaleDateString('en-CA', { timeZone: tz });
const date = /^\d{4}-\d{2}-\d{2}$/.test(String((P.args || {}).date || '')) ? P.args.date : today;
const d0 = new Date(date + 'T12:00:00Z');
const p = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).formatToParts(d0).map(x => [x.type, x.value]));
const mins = Math.round((Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute) - d0.getTime()) / 60000);
const offset = (mins >= 0 ? '+' : '-') + String(Math.floor(Math.abs(mins) / 60)).padStart(2, '0') + ':' + String(Math.abs(mins) % 60).padStart(2, '0');
return [{ json: { ...c, timezone: tz, offset, today, country_code: c.country_code || '92', currency_code: c.currency_code || 'PKR', currency_word: c.currency_word || 'rupees' } }];

